import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { build, BuildOptions } from './build';

const LIVE_RELOAD_SCRIPT = '<script>(function(){var s=new WebSocket(\'ws://\'+location.host+\'/__ssg_livereload\');s.onmessage=function(e){if(e.data===\'reload\')location.reload();};})();</script>';

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html',
  '.css': 'text/css',
  '.js': 'application/javascript',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
};

function getMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return MIME_TYPES[ext] || 'application/octet-stream';
}

export interface ServeOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  port: number;
}

export interface ServerInstance {
  server: http.Server;
  ready: Promise<void>;
  close(): Promise<void>;
}

export function serve(options: ServeOptions): ServerInstance {
  const { contentDir, outputDir, templatesDir, port } = options;

  const buildOpts: BuildOptions = { contentDir, outputDir, templatesDir };
  build(buildOpts);

  const wss = new WebSocketServer({ noServer: true });

  const server = http.createServer((req, res) => {
    if (!req.url) {
      res.writeHead(404);
      res.end();
      return;
    }

    let filePath = path.join(outputDir, req.url === '/' ? 'index.html' : req.url);
    filePath = path.normalize(filePath);

    if (!filePath.startsWith(path.resolve(outputDir))) {
      res.writeHead(403);
      res.end();
      return;
    }

    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
      res.writeHead(404);
      res.end('Not Found');
      return;
    }

    const ext = path.extname(filePath).toLowerCase();
    const mimeType = getMimeType(filePath);

    let content = fs.readFileSync(filePath);

    if (ext === '.html') {
      const html = content.toString('utf-8');
      const injectedHtml = html.replace('</body>', LIVE_RELOAD_SCRIPT + '</body>');
      content = Buffer.from(injectedHtml, 'utf-8');
    }

    res.writeHead(200, { 'Content-Type': mimeType });
    res.end(content);
  });

  server.on('upgrade', (request, socket, head) => {
    if (request.url === '/__ssg_livereload') {
      wss.handleUpgrade(request, socket, head, (ws) => {
        wss.emit('connection', ws, request);
      });
    } else {
      socket.destroy();
    }
  });

  let rebuildTimeout: NodeJS.Timeout | null = null;
  const clients: Set<WebSocket> = new Set();

  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => {
      clients.delete(ws);
    });
  });

  function triggerRebuild() {
    if (rebuildTimeout) {
      clearTimeout(rebuildTimeout);
    }
    rebuildTimeout = setTimeout(() => {
      try {
        build(buildOpts);
        for (const client of clients) {
          if (client.readyState === WebSocket.OPEN) {
            client.send('reload');
          }
        }
      } catch {
        // Silently handle build errors during watch
      }
    }, 300);
  }

  const watchDirs: string[] = [contentDir];
  if (templatesDir) {
    watchDirs.push(templatesDir);
  }

  const watcher = chokidar.watch(watchDirs, {
    ignoreInitial: true,
  });

  watcher.on('all', () => {
    triggerRebuild();
  });

  const ready = new Promise<void>((resolve) => {
    server.once('listening', resolve);
  });

  server.listen(port);

  return {
    server,
    ready,
    close(): Promise<void> {
      return new Promise((resolve) => {
        watcher.close();
        wss.close(() => {
          for (const client of clients) {
            client.terminate();
          }
          clients.clear();
          server.close(() => resolve());
        });
      });
    },
  };
}

